     3	// What a claimant reports: how much damage an item of a given type took.
     4	export interface Damage {
     5	  itemType: string;
     6	  amount: number;
     7	}
     8	
     9	// A reported damage once the office has decided which covered item answers
    10	// for it: the amount to value, bound to the item it will be valued against.
    11	export interface SettledDamage {
    12	  damagedItem: Item;
    13	  amount: number;
    14	}
    15	
    16	// Whether the office admits the reports at all, before it asks which items
    17	// answer for them. A damage report states how much damage an item took, so a
    18	// negative amount is not a reduced payout but a report the office refuses.
    19	// The office refuses the whole claim, so every report is admitted before any
    20	// is settled. Further admissibility rules belong here, alongside this one.
    21	export function admitDamages(damages: Damage[]): void {
    22	  for (const damage of damages) {
    23	    if (damage.amount < 0) {
    24	      throw new Error(
    25	        `A damage amount cannot be negative, but "${damage.itemType}" reports ${damage.amount}`,
    26	      );
    27	    }
    28	  }
    29	}
    30	
    31	// Which covered item answers for each reported damage. The office only settles
    32	// damage to items it actually covers, and each covered item answers for at
    33	// most one damage, so a type outside the policy -- or reported more often
    34	// than the policy covers it -- is not a smaller payout but a claim it refuses.
    35	export function settledDamagesOf(
    36	  items: Item[],
    37	  damages: Damage[],
    38	): SettledDamage[] {
    39	  const unclaimedItems = [...items];
    40	  return damages.map((damage) => {
    41	    const index = unclaimedItems.findIndex(
    42	      (item) => item.type === damage.itemType,
    43	    );
    44	    if (index === -1) {
    45	      throw new Error(
    46	        `The policy does not cover an item of type "${damage.itemType}"`,
    47	      );
    48	    }
    49	    return {
    50	      damagedItem: unclaimedItems.splice(index, 1)[0],
    51	      amount: damage.amount,
    52	    };
    53	  });
    54	}
