    23	// A deductible of 100 G applies per damage event, that is, once per
    24	// damaged item rather than once per incident.
    25	const DEDUCTIBLE_PER_DAMAGE = 100;
    26	
    27	// What a single settled damage is worth: the reimbursable share of the damage
    28	// amount, less the deductible the office withholds from every damage event.
    29	// Which item the report refers to is settled before this point, so the
    30	// valuation turns on the item itself, never on the policy.
    31	function valueOf({ damagedItem, amount }: SettledDamage): number {
    32	  return amount * reimbursementShareOf(damagedItem) - DEDUCTIBLE_PER_DAMAGE;
    33	}
