     6	// A scenario is one customer's dealings with the office: a sequence of steps
     7	// the office works through in order, each answered against what the earlier
     8	// steps left behind.
     9	export interface QuoteStep {
    10	  op: "quote";
    11	  items: Item[];
    12	}
    13	
    14	export interface ClaimStep {
    15	  op: "claim";
    16	  policy: number;
    17	  incident: Incident;
    18	}
    19	
    20	export type Step = QuoteStep | ClaimStep;
    21	
    22	export interface Scenario {
    23	  customer: Customer;
    24	  steps: Step[];
    25	}
    26	
    27	export type Result =
    28	  | { premium: number }
    29	  | { payout: number; remainingCap: number };
    30	
    31	// A policy as the office holds it while the scenario runs: what it covers,
    32	// and how much of its cap is still available to pay out.
    33	interface Policy {
    34	  items: Item[];
    35	  remainingCap: number;
    36	}
    37	
    38	// The register of policies the scenario's quote steps have opened. A claim
    39	// names the step that opened the policy it draws on, so a step that opened no
    40	// policy is not an empty claim but a scenario the office refuses.
    41	type PolicyRegister = Map<number, Policy>;
    42	
    43	function policyOpenedBy(register: PolicyRegister, stepIndex: number): Policy {
    44	  const policy = register.get(stepIndex);
    45	  if (policy === undefined) {
    46	    throw new Error(`Step ${stepIndex} did not create a policy to claim on`);
    47	  }
    48	  return policy;
    49	}
    50	
    51	// A claim draws on its policy's remaining cap and leaves the policy with less
    52	// cap for the claims after it.
    53	function settleAgainst(policy: Policy, incident: Incident): Result {
    54	  const settlement = claim(policy.items, policy.remainingCap, incident);
    55	  policy.remainingCap = settlement.remainingCap;
    56	  return settlement;
    57	}
    58	
    59	// Quoting a step opens the policy later claims draw on, keyed by the step that
    60	// opened it.
    61	function openPolicy(
    62	  register: PolicyRegister,
    63	  stepIndex: number,
    64	  items: Item[],
    65	): void {
    66	  register.set(stepIndex, { items, remainingCap: capOf(items) });
    67	}
    68	
    69	// The office works through the scenario's steps in order. Two things carry
    70	// from one step to the next for different reasons: the policies the quotes
    71	// opened, which claims draw on, and how many contracts the customer has taken
    72	// out so far, which decides whether the next quote is a follow-up.
    73	export function resultsFor(scenario: Scenario): Result[] {
    74	  const register: PolicyRegister = new Map();
    75	  let previousQuoteCount = 0;
    76	
    77	  return scenario.steps.map((step, stepIndex) => {
    78	    if (step.op === "claim") {
    79	      return settleAgainst(policyOpenedBy(register, step.policy), step.incident);
    80	    }
    81	    const premium = quote(scenario.customer, step.items, previousQuoteCount);
    82	    previousQuoteCount += 1;
    83	    openPolicy(register, stepIndex, step.items);
    84	    return { premium };
    85	  });
    86	}
