  const policyBasePremium = policyBasePremiumOf(items);
  const premium =
    policyBasePremium +
    itemRiskSurchargesOf(items) +
    policyWideModifiersOf(standing, policyBasePremium) +
    PROCESSING_FEE;
  return roundAmountChargedInMHPCOsFavour(premium);
}
